changeSet.sql:
DELETE FROM ts_supervisor_data
WHERE user_id IN (SELECT user_id FROM ts_single_role_to_user WHERE single_role = 'SUPERVISOR');
WITH supervisors AS (
    DELETE FROM ts_single_role_to_user WHERE single_role = 'SUPERVISOR' RETURNING user_id
)
DELETE FROM ts_user WHERE id IN (SELECT user_id FROM supervisors);

ALTER TABLE ts_single_role_to_user DROP CONSTRAINT ck_ts_single_role_to_user_single_role;
ALTER TABLE ts_single_role_to_user ADD CONSTRAINT ck_ts_single_role_to_user_single_role CHECK (
    single_role IN ('PARTICIPANT', 'OBSERVER')
);
ALTER TABLE ts_multiple_role_to_user DROP CONSTRAINT ck_ts_multiple_role_to_user_multiple_role;
ALTER TABLE ts_multiple_role_to_user ADD CONSTRAINT ck_ts_multiple_role_to_user_multiple_role CHECK (
    multiple_role IN ('DEVELOPER', 'STUDENT', 'ADMINISTRATOR', 'JUDGE', 'MANAGER', 'SUPERVISOR')
);
ALTER TABLE ts_cabinet_sign_in DROP CONSTRAINT ck_ts_cabinet_sign_in_user_kind;
ALTER TABLE ts_cabinet_sign_in ADD CONSTRAINT ck_ts_cabinet_sign_in_user_kind CHECK (
    user_kind IN ('MULTIPLE_ROLE', 'PARTICIPANT', 'OBSERVER', 'SERVICE')
);

